import json,html
T=json.load(open('tokens/_t.json'));C=json.load(open('tokens/contrast.json'));cv=C['coral_vs_reference']
L=json.load(open('logo/_list.json'));I=json.load(open('icons/_list.json'))
def sw(n,h,txt='#fff'):return f'<div class="sw"><div style="background:{h};color:{txt}">{n}</div><code>{h}</code></div>'
pal=''.join(sw(k,v,'#1B2140' if k in('gold','gold-100','coral-100','blue-100','amber') else '#fff') for k,v in T['brand'].items())
neu=''.join(sw(k,v,'#1B2140' if k in('bg','surface','surface-2','line') else '#fff') for k,v in T['neutral'].items())
sem=''.join(sw(k,v,'#1B2140' if '100' in k else '#fff') for k,v in T['semantic'].items())
drk=''.join(sw(k,v,'#0B1530' if k not in('bg','surface','surface-2','line') else '#F3F5FB') for k,v in T['dark'].items())
rows=''.join(f'<tr><td>{r["name"]}</td><td><span class="chipc" style="background:{r["bg"]};color:{r["fg"]}">Aa</span> <code>{r["fg"]}</code> / <code>{r["bg"]}</code></td><td><b>{r["ratio"]}</b></td><td>{"✅" if r["AA"] else ("⚠️ solo grande" if r["AA_large"] else "❌")}</td><td>{r["use"]}</td></tr>' for r in C['contrast'])
V=T['vertical'];vn={'museos':('Museos','museum'),'justicia':('Justicia','scale'),'policia':('Policía','shield'),'educacion':('Educación','school')}
from colorlib import cr
vrows=''.join(f'<tr><td><b>{vn[k][0]}</b></td><td><span class="chipc" style="background:{v["light"]};color:#fff">{v["light"]}</span></td><td>{cr(v["light"],"#FFF8EC")} / blanco {cr("#FFFFFF",v["light"])}</td><td><span class="chipc" style="background:#0B1530;color:{v["dark"]}">{v["dark"]}</span></td><td>{cr(v["dark"],"#0B1530")}</td></tr>' for k,v in V.items())
logos=''.join(f'<figure class="lg {"dk" if ("on-dark" in n or "symbol-dark" in n) else ""}"><img src="logo/{n}.svg" alt="{n}"><figcaption><a href="logo/{n}.svg">SVG</a> · <a href="logo/png/{n}.png">PNG</a> · {n}</figcaption></figure>' for n in L)
icons=''.join(f'<figure class="icn"><img src="icons/{k}.svg" alt="{k}"><figcaption>{k}</figcaption></figure>' for k in I)
mis=''.join(f'<figure class="lg"><img src="logo/aula-umbrella-horizontal.svg" style="{s}"><figcaption>❌ {t}</figcaption></figure>' for s,t in [('transform:scaleX(1.4)','No deformar'),('filter:hue-rotate(140deg)','No cambiar colores'),('transform:rotate(-12deg)','No girar'),('background:repeating-linear-gradient(45deg,#2E5BFF 0 8px,#FF4250 8px 16px)','No sobre fondos ruidosos'),('opacity:.35','No bajar la opacidad'),('filter:drop-shadow(4px 4px 0 #000)','No añadir sombras')])
scr=['home','question','explanation','result','simulacro','home-dark']
screens=''.join(f'<figure class="ph"><a href="screens/{s}.png"><img src="screens/{s}.png" alt="{s}"></a><figcaption>{s}</figcaption></figure>' for s in scr)
tpls=''.join(f'<figure class="tp"><a href="templates/{f}"><img src="templates/{f}" alt=""></a><figcaption>{f}</figcaption></figure>' for f in ['instagram-post-1080.png','instagram-story-1080x1920.png','og-image-1200x630.png']+[f'appstore-6.7-{i}-1290x2796.png' for i in range(1,5)])
tone=[('¡Racha de 12 días! Sigue así.','Празднуем маленькие победы конкретно, с цифрой.'),('¡Casi! Era la B. Mira por qué.','Ошибка — не провал, а повод разобраться. Без «Incorrecto».'),('Hoy toca el tema 18. Son 6 minutos.','Конкретный и маленький следующий шаг снижает тревогу.'),('Tu racha está a salvo: hoy usamos tu día de descanso.','Без чувства вины: отдых — часть метода.'),('21,64 sobre 30. Por encima del corte orientativo.','Честные цифры и оговорка «orientativa», без обещаний.'),('Repasa tus 21 errores y sube un poco más.','Мотивация через действие, а не через давление.')]
ban=['«Garantía de aprobado» / «aprueba seguro»','«Duolingo» o comparaciones con otras apps','«¡Vas a perder tu racha!» (culpa, amenaza)','«Vidas», «ligas», rankings públicos','Sellos, escudos o logos del Estado o de ministerios','Mascotas o personajes']
tv=''.join(f'<tr><td><b>«{a}»</b></td><td>{b}</td></tr>' for a,b in tone)
page=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>aula! — Brandbook · C · Impulso</title>
<link rel="icon" href="favicon/favicon.svg"><link rel="stylesheet" href="ui/aula-ui.css"><style>
body{{background:var(--bg)}}.wrap{{max-width:1120px;margin:0 auto;padding:20px}}section{{padding:36px 0;border-bottom:2px solid var(--line)}}h2{{font-size:30px}}h3{{margin-top:20px}}
.toc{{display:flex;flex-wrap:wrap;gap:8px}}.toc a{{text-decoration:none}}
.grid{{display:grid;gap:14px;grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}}
.sw div{{height:72px;border-radius:14px;display:flex;align-items:flex-end;padding:8px;font-weight:800;font-size:13px;border:1px solid rgba(0,0,0,.06)}}.sw code{{font-size:12px}}
table{{border-collapse:collapse;width:100%;font-size:14px;background:#fff;border-radius:16px;overflow:hidden}}td,th{{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}}
.tablewrap{{overflow-x:auto}}.chipc{{display:inline-block;padding:3px 8px;border-radius:8px;font-weight:900;font-family:var(--font-mono);font-size:12px}}
.lg{{margin:0;background:#fff;border:2px solid var(--line);border-radius:16px;padding:12px}}.lg.dk{{background:var(--navy-900)}}.lg img{{max-width:100%;height:56px;display:block}}.lg figcaption{{font-size:11px;margin-top:6px;color:var(--muted);word-break:break-all}}.lg.dk figcaption,.lg.dk a{{color:#A9B4D0}}
.lgs{{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(250px,1fr))}}
.icn{{margin:0;text-align:center;font-size:11px;color:var(--muted)}}.icn img{{width:32px;height:32px}}.icons{{display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:10px;background:#fff;border-radius:16px;padding:16px}}
.ph{{margin:0}}.ph img{{width:100%;border-radius:22px;border:6px solid var(--navy-900)}}.phs{{display:grid;gap:14px;grid-template-columns:repeat(auto-fill,minmax(160px,1fr))}}figcaption{{font-size:12px;font-weight:700}}
.tp{{margin:0}}.tp img{{width:100%;border-radius:12px}}.tps{{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));align-items:start}}
.full img{{width:100%;border-radius:16px;border:2px solid var(--line)}}
.type p{{margin:4px 0}}a{{color:var(--blue-700)}}
</style></head><body><div class="wrap">
<header style="display:flex;justify-content:space-between;align-items:center;padding:8px 0 20px"><img src="logo/aula-umbrella-horizontal.svg" height="44" alt="aula!"><span class="badge" style="background:var(--navy-900);color:var(--gold)">Brandbook v1 · C · Impulso · borrador</span></header>
<div class="navy" style="border-radius:28px;padding:32px"><h1 style="font-size:44px;color:#fff">Estudia como se examina<span style="color:#FF7A85">!</span></h1><p style="color:#C9D2E8;font-weight:600;font-size:18px;max-width:720px">Juguetón pero adulto. Coral para la energía, navy + oro para el método y los logros. La racha y la motivación en el centro.</p>
<div class="toc">{''.join(f'<a class="chip" href="#{a}">{b}</a>' for a,b in [('logo','1 Logo'),('color','2 Color'),('coral','Coral vs ref.'),('navy','3 Navy + oro'),('type','4 Tipografía'),('ui','5 UI kit'),('vert','6 Verticales'),('voz','7 Tono'),('screens','8 Pantallas'),('web','9 Web'),('icons','10 Iconos e ilustraciones'),('appicon','11 App icon / favicon'),('tpl','12 Plantillas'),('tokens','13 Tokens')])}</div></div>
<section id="logo"><h2>1 · Logo</h2><p>Wordmark <b>«aula!»</b> (Nunito Black, contornos) + símbolo <b>«a!»</b> en cuadrado redondeado. El «!» es el impulso: el momento de «¡lo tengo!». Cada vertical: símbolo en su color + nombre de la vertical.</p>
<div class="lgs">{logos}</div>
<h3>Zona de respeto y tamaño mínimo</h3><div class="full" style="max-width:520px"><img src="logo/aula-clearspace.svg"></div>
<p>Zona de respeto = <b>x</b> (altura de la «a» del wordmark) en los cuatro lados. Tamaño mínimo: horizontal <b>96 px / 24 mm</b> de ancho; símbolo <b>16 px</b> (favicon) / <b>8 mm</b> en impresión. Por debajo de 120 px se omite el nombre de la vertical.</p>
<h3>Usos incorrectos</h3><div class="lgs">{mis}</div></section>
<section id="color"><h2>2 · Color</h2><h3>Marca</h3><div class="grid">{pal}</div><h3>Neutros</h3><div class="grid">{neu}</div><h3>Semánticos (éxito = teal, no verde Duolingo)</h3><div class="grid">{sem}</div>
<p><b>Reglas:</b> coral #FF4250 solo en rellenos, iconos y texto ≥ 24 px (o 18,5 px bold). Texto coral normal → <b>coral-700 #C8162B</b>. Botón primario grande (texto ≥ 19 px, 800) sobre coral = 3,42 (válido como texto grande, ≥ 3:1); en textos de botón pequeños usar coral-700. Racha = coral + navy; XP y logros = oro.</p>
<h3>Tabla de contraste (WCAG 2.x)</h3><div class="tablewrap"><table><tr><th>Par</th><th>Muestra</th><th>Ratio</th><th>AA</th><th>Uso</th></tr>{rows}</table></div></section>
<section id="coral"><h2>Coral final vs. referencia competidor</h2><div class="full"><img src="ui/coral-vs-reference.png" alt=""></div><p>#FF4250: tono {cv["hue_final"]}° (rosa-rojo) frente a #EF7746: tono {cv["hue_ref"]}° (naranja). Diferencia de tono {cv["hue_diff"]}°, ΔE2000 {cv["dE2000"]}. El coral anterior #FF6B3D estaba a ΔE {cv["dE2000_old_FF6B3D"]}.</p></section>
<section id="navy"><h2>3 · Navy + oro (pareja oscura de la marca)</h2><p>No es solo «modo oscuro»: navy + oro aparece en el hero, secciones oscuras, cabecera de la app, racha, XP y footer. En modo oscuro se convierte en la base.</p><div class="grid">{drk}</div>
<div class="phs" style="margin-top:16px"><figure class="ph"><img src="screens/home-dark.png"><figcaption>home · modo oscuro</figcaption></figure><figure class="ph"><img src="screens/home.png"><figcaption>home · claro con cabecera navy</figcaption></figure></div>
<div class="full" style="margin-top:16px"><img src="ui/ui-kit-dark.png"></div></section>
<section id="type"><h2>4 · Tipografía</h2><p><b>Nunito</b> (SIL OFL 1.1, autoalojada, <a href="fonts/OFL-Nunito.txt">licencia</a>) para todo. Pareja opcional: <b>JetBrains Mono</b> (OFL, <a href="fonts/OFL-JetBrainsMono.txt">licencia</a>) solo para fórmulas y cronómetro.</p>
<div class="card type">{''.join(f'<p style="font:{v.split()[1]} {v.split()[0].split("/")[0]}px/{v.split()[0].split("/")[1]} var(--font-sans)"><span class="muted" style="font-size:12px;font-weight:800;display:inline-block;width:150px">{k} · {v}</span>Estudia como se examina</p>' for k,v in T['type'].items())}<p class="code" style="font-size:14px"><span class="muted" style="font-size:12px;display:inline-block;width:150px">mono · 14/1.6</span>15 + (61 − 30) ÷ (100 − 30) × 15 = 21,64</p></div></section>
<section id="ui"><h2>5 · UI kit</h2><div class="full"><img src="ui/ui-kit.png" alt="UI kit"></div><p>CSS: <a href="ui/aula-ui.css">ui/aula-ui.css</a> · HTML: <a href="ui/ui-kit.html">ui-kit.html</a></p></section>
<section id="vert"><h2>6 · Verticales</h2><p>El coral y el navy/oro son siempre de aula!. La vertical solo aparece en: <b>badge</b>, <b>línea izquierda de tarjeta</b> (6 px), <b>símbolo del logo</b> y <b>pestaña activa de temas</b>. Nunca en el CTA principal.</p>
<div class="tablewrap"><table><tr><th>Vertical</th><th>Claro</th><th>Contraste (bg / blanco)</th><th>Oscuro</th><th>sobre navy</th></tr>{vrows}</table></div></section>
<section id="voz"><h2>7 · Tono de voz</h2><p>Tuteo, frases cortas, energía sin presión. Celebramos lo pequeño, explicamos el error, nunca culpamos.</p><div class="tablewrap"><table><tr><th>Así sí (ES)</th><th>Por qué (RU)</th></tr>{tv}</table></div>
<h3>Así no</h3><ul>{''.join(f'<li>{b}</li>' for b in ban)}</ul><p>Pie legal: «Aviso legal · Privacidad · Aula es una herramienta independiente, no afiliada a ningún ministerio ni organismo público.» El contenido de IA siempre lleva «Contenido generado por IA» + fuente o «Sin fuente».</p></section>
<section id="screens"><h2>8 · Pantallas de la app (390 px)</h2><div class="phs">{screens}</div></section>
<section id="web"><h2>9 · Web: cabecera, hero con misión y footer</h2><div class="full"><img src="web/site-desktop-1280.png"></div><div class="phs" style="margin-top:14px"><figure class="ph"><img src="web/site-mobile-390.png"><figcaption>móvil 390</figcaption></figure></div></section>
<section id="icons"><h2>10 · Iconos e ilustraciones</h2><p>{len(I)} iconos SVG 24 px, trazo 2 px, extremos redondeados, <code>currentColor</code>.</p><div class="icons">{icons}</div>
<h3>Ilustraciones spot (planas, sin personajes)</h3><div class="grid">{''.join(f'<figure class="icn"><img src="illustrations/{k}.svg" style="width:140px;height:140px"><figcaption>{k}</figcaption></figure>' for k in ['racha','temario','simulacro','meta'])}</div></section>
<section id="appicon"><h2>11 · App icon y favicon</h2><div style="display:flex;gap:16px;align-items:end;flex-wrap:wrap"><img src="app-icon/ios-180.png" width="120" style="border-radius:27px"><img src="app-icon/android-xxxhdpi-192.png" width="96" style="border-radius:50%"><img src="favicon/favicon-64.png" width="64"><img src="favicon/favicon-32.png"><img src="favicon/favicon-16.png"></div>
<p>iOS: 20, 29, 40, 58, 60, 76, 80, 87, 120, 152, 167, 180, 1024 · Android: 48–192 + Play 512 · Favicon: ico (16/32/48), svg, png 16–512, apple-touch 180, <a href="favicon/site.webmanifest">manifest</a>, <a href="favicon/head-snippet.html">snippet &lt;head&gt;</a>.</p></section>
<section id="tpl"><h2>12 · Plantillas</h2><div class="tps">{tpls}</div><p><a href="templates/email-signature.html">Firma de email (HTML)</a> — los campos entre corchetes son placeholders.</p></section>
<section id="tokens"><h2>13 · Tokens para código</h2><p><a href="tokens/aula-tokens.json">aula-tokens.json</a> · <a href="tokens/aula-tokens.css">aula-tokens.css</a> (<code>:root</code> claro, <code>[data-theme="dark"]</code>, <code>[data-vertical="…"]</code> → <code>--accent-v</code>) · <a href="tokens/contrast.json">contrast.json</a></p></section>
<footer style="padding:24px 0;color:var(--muted);font-size:14px">aula! brandbook · borrador de diseño 31.10.2026 · Aviso legal · Privacidad · no afiliada a ningún ministerio ni organismo público</footer>
</div></body></html>'''
open('index.html','w').write(page)
